import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { FormControl, FormDescription, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { schema } from '@/lib/zod-form/schema';

type StripIndexSignature<T> = T extends Date | File | FileList | Blob | RegExp
  ? T
  : T extends readonly (infer U)[]
    ? StripIndexSignature<U>[]
    : T extends object
      ? {
          [K in keyof T as string extends K
            ? never
            : number extends K
              ? never
              : symbol extends K
                ? never
                : K]: StripIndexSignature<T[K]>;
        }
      : T;

type FormData = StripIndexSignature<z.input<typeof schema>>;
type FormOutput = StripIndexSignature<z.output<typeof schema>>;

const _resolver = zodResolver(schema);

export function GeneratedForm(props: {
  onSubmit: (data: FormOutput) => void;
  defaultValues?: Partial<FormData>;
  values?: FormData;
  fieldProps?: Record<string, Record<string, unknown>>;
}) {
  const form = useForm<FormData>({
    resolver: _resolver,
    defaultValues: props.defaultValues,
    values: props.values,
  });
  const { register, handleSubmit } = form;

  return (
    <form onSubmit={handleSubmit((data) => props.onSubmit(data as unknown as FormOutput))}>
      <FormItem>
        <FormLabel htmlFor="name">Name</FormLabel>
        <FormControl><input id="name" type="text" {...register('name')} /></FormControl>
        <FormMessage />
      </FormItem>
      <FormItem>
        <FormLabel htmlFor="email">Email</FormLabel>
        <FormControl><input id="email" type="email" {...register('email')} /></FormControl>
        <FormMessage />
      </FormItem>
      <FormItem>
        <FormLabel htmlFor="age">Age</FormLabel>
        <FormControl><input id="age" type="number" {...register('age')} /></FormControl>
        <FormMessage />
      </FormItem>
      <FormItem>
        <FormLabel htmlFor="subscribe">Subscribe to updates</FormLabel>
        <FormControl><input id="subscribe" type="checkbox" {...register('subscribe')} /></FormControl>
        <FormMessage />
      </FormItem>
      <button type="submit">Submit</button>
    </form>
  );
}

export default GeneratedForm;

